import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

// Network Base Endpoint Configuration matching your system standards
const API_BASE_URL = process.env.NODE_ENV === 'production'
  ? 'https://aiiot-1.onrender.com'
  : 'http://localhost:8000';

const DemandForecasting = () => {
  const navigate = useNavigate();
  const [forecastData, setForecastData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Fetch telemetry function block
  const fetchLiveDemandData = async () => {
    try {
const response = await fetch(`${API_BASE_URL}/api/weather/water-demand`);      if (!response.ok) {
        throw new Error(`Server returned status: ${response.status}`);
      }
      const result = await response.json();
      if (result.success) {
        setForecastData(result);
        setError(null);
      } else {
        throw new Error(result.error || 'Failed parsing live data arrays.');
      }
    } catch (err) {
      console.error('Error connecting to hydraulic telemetry stream:', err);
      setError(err.message || 'Failed connecting to real-time S3 telemetry streams.');
    } finally {
      setLoading(false);
    }
  };

  // Setup Lifecycle Polling Loop Hooks
  useEffect(() => {
    fetchLiveDemandData();

    // Establish dynamic background update polling loop execution cycle every 30 seconds
    const telemetryInterval = setInterval(fetchLiveDemandData, 30000);
    return () => clearInterval(telemetryInterval);
  }, []);

  return (
    <div className="demand-forecasting-container" style={{ padding: '20px', fontFamily: 'Arial, sans-serif', maxWidth: '1200px', margin: '0 auto' }}>
      
      {/* Back to Weather Dashboard */}
      <button 
        className="btn btn-secondary" 
        onClick={() => navigate('/weather-home')}
        style={{ marginBottom: '20px', cursor: 'pointer', padding: '10px 15px', borderRadius: '4px', border: '1px solid #cbd5e1', backgroundColor: '#f1f5f9' }}
      >
        <i className="fas fa-arrow-left" style={{ marginRight: '8px' }}></i> Back to Weather Homepage
      </button>

      <header style={{ borderBottom: '2px solid #e2e8f0', paddingBottom: '15px', marginBottom: '30px' }}>
        <h1 style={{ color: '#1e3a8a', margin: '0 0 10px 0' }}>Real-time Hydraulic Demand Forecasting</h1>
        <p style={{ color: '#475569', margin: '0' }}>
          Live operational data from the Artificial Intelligence Integrated Water Distribution system bed.
        </p>
      </header>

      {/* Asynchronous System Handling Interceptors */}
      {loading ? (
        <div style={{ padding: '40px', textAlign: 'center', color: '#64748b' }}>
          <div style={{ width: '30px', height: '30px', border: '3px solid #e2e8f0', borderTop: '3px solid #0284c7', borderRadius: '50%', animation: 'spin 1s linear infinite', margin: '0 auto 15px auto' }}></div>
          <p>Connecting to AWS S3 telemetry buffers...</p>
          <style>{`@keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }`}</style>
        </div>
      ) : error ? (
        <div style={{ padding: '20px', background: '#fef2f2', border: '1px solid #fee2e2', borderRadius: '6px', color: '#991b1b', marginBottom: '25px' }}>
          <h4><i className="fas fa-exclamation-triangle" style={{ marginRight: '8px' }}></i> Operational Telemetry Offline</h4>
          <p style={{ margin: '5px 0 15px 0' }}>{error}</p>
          <button onClick={fetchLiveDemandData} style={{ padding: '8px 12px', backgroundColor: '#991b1b', color: '#ffffff', border: 'none', borderRadius: '4px', cursor: 'pointer' }}>
            Retry Telemetry Fetch
          </button>
        </div>
      ) : (
        <>
          {/* Real-time Content Display Block */}
          <div style={{ background: '#ffffff', borderRadius: '8px', boxShadow: '0 4px 6px -1px rgba(0,0,0,0.1)', padding: '20px', marginBottom: '30px', border: '1px solid #e2e8f0' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', marginBottom: '20px', gap: '10px' }}>
              <h3 style={{ margin: '0', color: '#334155' }}>
                <i className="fas fa-satellite-dish" style={{ marginRight: '8px', color: '#10b981' }}></i>
                Live Forecast Execution Cycle: <span style={{ fontWeight: 'normal', color: '#64748b' }}>{forecastData?.timestamp}</span>
              </h3>
              <span style={{ fontSize: '12px', background: '#d1fae5', color: '#065f46', padding: '4px 10px', borderRadius: '12px', fontWeight: 'bold' }}>
                <i className="fas fa-sync-alt fa-spin" style={{ marginRight: '5px' }}></i> Auto-refreshing Live from S3
              </span>
            </div>

            {/* Demand Metrics Grid */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', gap: '20px' }}>
              {forecastData?.demand && Object.keys(forecastData.demand).length > 0 ? (
                Object.entries(forecastData.demand).map(([nodeName, val]) => (
                  <div key={nodeName} style={{ background: '#f8fafc', padding: '20px', borderRadius: '6px', borderLeft: '4px solid #3b82f6', border: '1px solid #f1f5f9', borderLeftWidth: '4px' }}>
                    <h4 style={{ margin: '0 0 10px 0', color: '#1e40af', textTransform: 'capitalize' }}>
                      {nodeName.replace(/_/g, ' ')}
                    </h4>
                    <p style={{ fontSize: '28px', fontWeight: 'bold', margin: '0', color: '#0f172a' }}>
                      {val} <span style={{ fontSize: '14px', fontWeight: 'normal', color: '#64748b' }}>m³/h</span>
                    </p>
                  </div>
                ))
              ) : (
                <p style={{ color: '#64748b' }}>No node matrices populated for this parsing sequence.</p>
              )}
            </div>
          </div>

          {/* Infrastructure Intent Explainer Block */}
          <div style={{ background: '#eff6ff', border: '1px solid #bfdbfe', borderRadius: '6px', padding: '20px' }}>
            <h4 style={{ margin: '0 0 10px 0', color: '#1e40af' }}>
              <i className="fas fa-info-circle" style={{ marginRight: '8px' }}></i> Active Stakeholder Network Coordination
            </h4>
            <p style={{ margin: '0', color: '#1e3a8a', lineHeight: '1.6', fontSize: '14px' }}>
              This portal streams calculated pipeline demand matrices directly from your edge telemetry network. The platform correlates hydraulic data with dynamic regional factors to automatically optimize valve distribution patterns.
            </p>
          </div>
        </>
      )}
    </div>
  );
};

export default DemandForecasting;
